def transform(grid):
    h, w = len(grid), len(grid[0])
    full_rows = [i for i, row in enumerate(grid) if len(set(row)) == 1]
    full_cols = [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]
    out = [row[:] for row in grid]
    for i in full_rows:
        for j in range(w):
            out[i][j] = 2
    for j in full_cols:
        for i in range(h):
            out[i][j] = 2
    return out
